const input = $input.item.json;
const artifactId = input.artifact_id ?? input.requested_artifact_id;

if (!input.artifact_id || !input.content_base64) {
  return {
    json: {
      sender_id: input.sender_id,
      pdf_artifact_id: artifactId,
      pdf_found: false,
      status_code: 404,
      reply: 'PDF não encontrado para este remetente.',
    },
  };
}

const fileName = String(input.file_name || 'curriculo.pdf').replace(/[\r\n"]/g, '_');
const fileExtension = fileName.split('.').pop() || 'pdf';
const sizeBytes = Number(input.size_bytes ?? 0);

return {
  json: {
    sender_id: input.sender_id,
    pdf_artifact_id: input.artifact_id,
    pdf_filename: fileName,
    pdf_mime_type: input.mime_type || 'application/pdf',
    pdf_size_bytes: Number.isFinite(sizeBytes) ? sizeBytes : null,
    pdf_found: true,
    status_code: 200,
    reply: 'PDF recuperado do armazenamento local.',
  },
  binary: {
    data: {
      data: input.content_base64,
      mimeType: input.mime_type || 'application/pdf',
      fileName,
      fileExtension,
      fileSize: Number.isFinite(sizeBytes) ? String(sizeBytes) : undefined,
    },
  },
};

const body = $json.body ?? {};
const headers = $json.headers ?? {};
const grantToken = String(
  headers['x-download-grant'] ??
  headers['X-Download-Grant'] ??
  ''
).trim();

return {
  json: {
    sender_id: String(body.sender_id ?? '').trim(),
    pdf_artifact_id: String(body.artifact_id ?? '').trim(),
    grant_token_present: grantToken.length > 0,
    grant_token: grantToken,
  },
};

const input = $input.item.json;

return {
  json: {
    status_code: 403,
    grant_valid: false,
    sender_id: input.sender_id,
    pdf_artifact_id: input.pdf_artifact_id,
    reply: 'Token de download ausente, inválido, expirado ou revogado.',
  },
};
